import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Papa from "papaparse";
import "../App.css";

function LibraryPage() {
  const [searchText, setSearchText] = useState("");
  const [activeCategory, setActiveCategory] = useState("news");
  const [newsData, setNewsData] = useState([]);
  const [blogData, setBlogData] = useState([]);

  // Animation variants
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  // CSV 파일에서 데이터 로드
  useEffect(() => {
    fetch("/hanssem_contents.csv")
      .then((response) => response.text())
      .then((csvText) => {
        Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            const data = results.data;

            // 날짜 파싱 함수 (YYYY-MM-DD 형식)
            const parseDate = (dateStr) => {
              if (!dateStr) return new Date(0);
              const parts = dateStr.split('-');
              if (parts.length === 3) {
                return new Date(parts[0], parts[1] - 1, parts[2]);
              }
              return new Date(dateStr);
            };

            // 뉴스와 블로그 데이터 분리 및 최신순 정렬
            const news = data
              .filter(item => item.source === 'news')
              .sort((a, b) => parseDate(b.pubdate) - parseDate(a.pubdate))
              .slice(0, 10); // 최신 10개만

            const blog = data
              .filter(item => item.source === 'blog')
              .sort((a, b) => parseDate(b.pubdate) - parseDate(a.pubdate))
              .slice(0, 10); // 최신 10개만

            setNewsData(news);
            setBlogData(blog);
          },
        });
      })
      .catch((error) => console.error("CSV 로드 오류:", error));
  }, []);

  // 카테고리 데이터
  const categories = [
    {
      name: "News & Blogs",
      subtitle: "뉴스 & 블로그",
      items: [],
    },
    {
      name: "Research Papers",
      subtitle: "논문",
      items: [],
    },
    {
      name: "Trends & Reports",
      subtitle: "트렌드 & 리포트",
      items: [],
    },
    {
      name: "References & Guides",
      subtitle: "레퍼런스",
      items: [],
    },
  ];

  // 추천 자료 데이터 (목업)
  const recommendedAssets = [
    {
      id: 1,
      title: "미니멀리즘 컨셉 거실 디자인",
      author: "서울 연대학",
      rating: 4.9,
      imageUrl: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=500",
    },
    {
      id: 2,
      title: "모던 키친 디자인 가이드 2024",
      author: "한샘 디자인팀",
      rating: 4.8,
      imageUrl: "https://images.unsplash.com/photo-1556912172-45b7abe8b7e1?w=500",
    },
    {
      id: 3,
      title: "따뜻한 감성의 침실 인테리어",
      author: "인테리어 스튜디오",
      rating: 4.7,
      imageUrl: "https://images.unsplash.com/photo-1616594039964-ae9021a400a0?w=500",
    },
    {
      id: 4,
      title: "우아한 다이닝룸 디자인",
      author: "홈스타일링 연구소",
      rating: 4.6,
      imageUrl: "https://images.unsplash.com/photo-1617806118233-18e1de247200?w=500",
    },
    {
      id: 5,
      title: "편안한 욕실 디자인",
      author: "공간 플래너",
      rating: 4.5,
      imageUrl: "https://images.unsplash.com/photo-1552321554-5fefe8c9ef14?w=500",
    },
  ];

  // 전체 자료 데이터 (목업)
  const allAssets = [
    {
      id: 1,
      title: "2024 모던 거실 트렌드",
      author: "한샘 디자인팀",
      rating: 4.7,
      imageUrl: "https://images.unsplash.com/photo-1567016432779-094069958ea5?w=500",
      category: "Design",
    },
    {
      id: 2,
      title: "내추럴 우드 플로링 가이드",
      author: "건축 자재 연구소",
      rating: 4.7,
      imageUrl: "https://images.unsplash.com/photo-1615874959474-d609969a20ed?w=500",
      category: "Trend",
    },
    {
      id: 3,
      title: "스마트 홈 인테리어 가이드",
      author: "홈 IoT 연구소",
      rating: 4.8,
      imageUrl: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=500",
      category: "Education",
    },
    {
      id: 4,
      title: "아이를 위한 안전한 방",
      author: "어린이 공간 연구소",
      rating: 4.6,
      imageUrl: "https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=500",
      category: "Human",
    },
    {
      id: 5,
      title: "북유럽 스타일 주방",
      author: "디자인 허브",
      rating: 4.9,
      imageUrl: "https://images.unsplash.com/photo-1556911220-bff31c812dba?w=500",
      category: "Design",
    },
    {
      id: 6,
      title: "맞춤형 가구 제작 가이드",
      author: "가구 공방",
      rating: 4.5,
      imageUrl: "https://images.unsplash.com/photo-1524758631624-e2822e304c36?w=500",
      category: "Education",
    },
    {
      id: 7,
      title: "효율적인 수납 솔루션",
      author: "정리 수납 전문가",
      rating: 4.7,
      imageUrl: "https://images.unsplash.com/photo-1595428774223-ef52624120d2?w=500",
      category: "Philosophy",
    },
    {
      id: 8,
      title: "공간을 여는 조명 디자인",
      author: "라이팅 스튜디오",
      rating: 4.8,
      imageUrl: "https://images.unsplash.com/photo-1513506003901-1e6a229e2d15?w=500",
      category: "Design",
    },
  ];

  // 필터 버튼 데이터
  const filters = ["All", "Design", "Human", "Philosophy", "Trend", "Education"];

  // 필터링 로직
  const filteredAssets = allAssets.filter((asset) => {
    const categoryMatch = activeFilter === "All" || asset.category === activeFilter;
    const searchMatch = asset.title.toLowerCase().includes(searchText.toLowerCase());
    return categoryMatch && searchMatch;
  });

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "linear-gradient(180deg, #f8f9fa 0%, #e9ecef 100%)",
        paddingTop: "0",
        marginTop: "0",
      }}
    >
      {/* Header Section */}
      <motion.div
        style={{
          textAlign: "center",
          padding: "60px 20px 40px",
          background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
          color: "#fff",
          marginBottom: "0",
          marginTop: "0",
        }}
        initial="hidden"
        animate="visible"
        variants={fadeUp}
      >
        <motion.h1
          style={{
            fontSize: "clamp(2.5rem, 5vw, 3.5rem)",
            fontWeight: 800,
            margin: "0 0 15px",
            textShadow: "2px 2px 4px rgba(0,0,0,0.2)",
          }}
          variants={fadeUp}
        >
          Asset Library
        </motion.h1>
        <motion.p
          style={{
            fontSize: "1.2rem",
            opacity: 0.95,
            margin: 0,
          }}
          variants={fadeUp}
        >
          인테리어 디자인 자료와 영감을 찾아보세요
        </motion.p>
      </motion.div>

      {/* Main Content */}
      <div style={{ display: "flex", maxWidth: "1400px", margin: "0 auto", gap: "30px" }}>
        {/* Sidebar */}
        <motion.aside
          style={{
            width: "280px",
            background: "#fff",
            padding: "30px 25px",
            borderRadius: "20px",
            boxShadow: "0 10px 30px rgba(0, 0, 0, 0.08)",
            margin: "30px 0 30px 30px",
            height: "fit-content",
            position: "sticky",
            top: "100px",
          }}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          variants={fadeUp}
        >
          <h2
            style={{
              fontSize: "1.5rem",
              fontWeight: 700,
              color: "#333",
              marginTop: 0,
              marginBottom: "30px",
            }}
          >
            카테고리
          </h2>

          {categories.map((category, index) => (
            <div key={index} style={{ marginBottom: "25px" }}>
              <h3
                style={{
                  fontSize: "1rem",
                  fontWeight: 600,
                  color: "#667eea",
                  marginBottom: "10px",
                  paddingLeft: "10px",
                }}
              >
                {category.name}
              </h3>
              <p
                style={{
                  fontSize: "0.85rem",
                  color: "#6c757d",
                  paddingLeft: "10px",
                  margin: 0,
                }}
              >
                {category.subtitle}
              </p>
            </div>
          ))}
        </motion.aside>

        {/* Content Area */}
        <div style={{ flex: 1, padding: "30px 30px 30px 0" }}>
          {/* Search Bar */}
          <motion.div
            style={{
              display: "flex",
              gap: "12px",
              marginBottom: "40px",
              flexWrap: "wrap",
            }}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            variants={fadeUp}
          >
            <input
              type="text"
              placeholder="Search any documents..."
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{
                flex: 1,
                minWidth: "250px",
                padding: "14px 20px",
                border: "2px solid #e9ecef",
                borderRadius: "12px",
                fontSize: "1rem",
                transition: "all 0.3s ease",
              }}
              onFocus={(e) => {
                e.target.style.borderColor = "#667eea";
                e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
              }}
              onBlur={(e) => {
                e.target.style.borderColor = "#e9ecef";
                e.target.style.boxShadow = "none";
              }}
            />
            <motion.button
              style={{
                padding: "14px 30px",
                background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                color: "#fff",
                border: "none",
                borderRadius: "12px",
                fontSize: "1rem",
                fontWeight: 600,
                cursor: "pointer",
                boxShadow: "0 8px 20px rgba(102, 126, 234, 0.3)",
              }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              Search
            </motion.button>
            <motion.button
              style={{
                padding: "14px 25px",
                background: "linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)",
                color: "#fff",
                border: "none",
                borderRadius: "12px",
                fontSize: "1rem",
                fontWeight: 600,
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                boxShadow: "0 8px 20px rgba(67, 233, 123, 0.3)",
              }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              <i className="fas fa-plus"></i>
              자료 업로드
            </motion.button>
          </motion.div>

          {/* News Section */}
          <motion.section
            style={{ marginBottom: "50px" }}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.2 }}
            variants={staggerContainer}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "25px",
              }}
            >
              <h2 style={{ fontSize: "1.8rem", fontWeight: 700, margin: 0, color: "#333" }}>
                <i className="fas fa-newspaper" style={{ marginRight: "10px", color: "#667eea" }}></i>
                최신 뉴스
              </h2>
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                gap: "20px",
              }}
            >
              {newsData.length > 0 ? (
                newsData.map((item, index) => (
                  <ContentCard key={index} item={item} variants={fadeUp} />
                ))
              ) : (
                <p style={{ color: "#6c757d", gridColumn: "1 / -1" }}>뉴스 데이터를 불러오는 중...</p>
              )}
            </div>
          </motion.section>

          {/* Blog Section */}
          <motion.section
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.2 }}
            variants={staggerContainer}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "25px",
              }}
            >
              <h2 style={{ fontSize: "1.8rem", fontWeight: 700, margin: 0, color: "#333" }}>
                <i className="fas fa-blog" style={{ marginRight: "10px", color: "#f093fb" }}></i>
                최신 블로그
              </h2>
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
                gap: "20px",
              }}
            >
              {blogData.length > 0 ? (
                blogData.map((item, index) => (
                  <ContentCard key={index} item={item} variants={fadeUp} />
                ))
              ) : (
                <p style={{ color: "#6c757d", gridColumn: "1 / -1" }}>블로그 데이터를 불러오는 중...</p>
              )}
            </div>
          </motion.section>
        </div>
      </div>
    </main>
  );
}

// Content Card Component for News and Blog
function ContentCard({ item, variants }) {
  return (
    <motion.a
      href={item.url}
      target="_blank"
      rel="noopener noreferrer"
      style={{
        backgroundColor: "#fff",
        borderRadius: "15px",
        overflow: "hidden",
        boxShadow: "0 5px 15px rgba(0, 0, 0, 0.08)",
        transition: "all 0.3s ease",
        cursor: "pointer",
        position: "relative",
        textDecoration: "none",
        display: "block",
      }}
      variants={variants}
      whileHover={{
        y: -8,
        boxShadow: "0 15px 30px rgba(0, 0, 0, 0.15)",
      }}
    >
      {/* Info */}
      <div style={{ padding: "20px" }}>
        <h3
          style={{
            fontSize: "1.1rem",
            fontWeight: 600,
            color: "#333",
            margin: "0 0 12px",
            lineHeight: "1.5",
            overflow: "hidden",
            display: "-webkit-box",
            WebkitLineClamp: 2,
            WebkitBoxOrient: "vertical",
          }}
        >
          {item.title}
        </h3>
        <div style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          fontSize: "0.9rem",
          color: "#6c757d",
        }}>
          <i className="fas fa-calendar-alt" style={{ color: "#667eea" }}></i>
          <span>{item.pubdate}</span>
        </div>
        <div style={{
          marginTop: "12px",
          paddingTop: "12px",
          borderTop: "1px solid #e9ecef",
        }}>
          <span style={{
            fontSize: "0.85rem",
            color: "#667eea",
            fontWeight: 600,
            display: "flex",
            alignItems: "center",
            gap: "5px",
          }}>
            자세히 보기
            <i className="fas fa-arrow-right"></i>
          </span>
        </div>
      </div>
    </motion.a>
  );
}

export default LibraryPage;
